// Regenerates src/types/generated/index.ts from the ts-rs output files.
import { readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = new URL("../src/types/generated/", import.meta.url).pathname;
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".ts") && f !== "index.ts")
  .sort();
const lines = [
  "// AUTO-GENERATED by scripts/gen-type-index.mjs from ts-rs bindings. Do not edit.",
  ...files.map((f) => `export type * from "./${f.replace(/\.ts$/, "")}";`),
  "",
];
writeFileSync(join(dir, "index.ts"), lines.join("\n"));
console.log(`index.ts: ${files.length} types`);
